/**
 * UNIT-TEST DATA ONLY. Hand-written rows shaped like the `adm_graph` and
 * `adm_topology` output contract in docs/DATA_LAYER.md ("Access paths, ACI
 * fabric and contracts (v2)"). Not search output and never shipped as demo
 * data; the lab-generated ACI fixtures replace it when they exist.
 *
 * A single ACI fabric: leaves 101–103, spines 201–202. Kubernetes node-a and
 * node-b are EPG endpoints; node-c sits behind a floating-SVI L3Out and is
 * attached by LLDP only. A Windows VM in EPG win-clients reaches the app
 * through each access method.
 */
import type { GraphArgs, Row } from "../rows";

