const svc = (name: string) => `service:${C}/shop/${name}/demo`;
const pod = (uid: string) => `pod:${C}/${uid}`;
const front = (service: string, frontend: string) =>
  `k8s_service:${C}/shop/${service}/${frontend}`;
const node = (name: string) => `node:${C}/${name}`;

