const n = (fields: Record<string, string | string[]>): Row => ({
  row_type: "node",
  ...fields,
});
const e = (fields: Record<string, string | string[]>): Row => ({
  row_type: "edge",
  evidence: [],
  count: "1",
  ...fields,
});
const frontDoor = (
  id: string,
  service: string,
  frontend: string,
  attrs: Record<string, string>,
) =>
  n({
    id,
    label: `${service} · ${frontend}`,
    kind: "endpoint",
    endpoint_kind: "k8s_service",
    namespace: "shop",
    cluster: C,
    addresses: frontend.split(":")[0],
    attr_service: service,
    attr_frontend: frontend,
    ...Object.fromEntries(
      Object.entries(attrs).map(([k, v]) => [`attr_${k}`, v]),
    ),
  });
const podRow = (
  id: string,
  label: string,
  host: string,
  owner: string,
  ip: string,
  ns = "shop",
) =>
  n({
    id,
    label,
    kind: "workload",
    namespace: ns,
    cluster: C,
    addresses: ip,
    attr_node: host,
    attr_owner: owner,
    attr_owner_kind: "Deployment",
  });

