const dev = (name: string, nodeId: number, role: string, ip: string): Row => ({
  row_type: "device",
  device_id: name,
  name,
  mgmt_ip: ip,
  device_kind: "switch",
  platform: role === "spine" ? "N9K-C9332D-GX2B" : "N9K-C93180YC-FX3",
  fabric: "apic:192.0.2.50",
  aci_node: `pod-1/node-${nodeId}`,
  role,
  sources: "aci",
});
const fabricLink = (
  leaf: string,
  lp: string,
  spine: string,
  sp: string,
): Row => ({
  row_type: "link",
  a_device: leaf,
  a_interface: lp,
  b_device: spine,
  b_interface: sp,
  link_source: "aci",
});

